.step-indicator {
    counter-reset: step;
}

.step-item {
    position: relative;
}

.step-item:not(:last-child)::after {
    content: "";
    position: absolute;
    top: 14px;
    left: 55%;
    width: 90%;
    height: 2px;
    background-color: #dee2e6;
    z-index: 0;
}

.step-item.completed:not(:last-child)::after {
    background-color: #198754;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    font-size: 0.8rem;
    font-weight: 600;
    position: relative;
    z-index: 1;
}

.step-btn {
    border: none;
    background: none;
    cursor: pointer;
}

.step-btn:hover .step-label {
    text-decoration: underline;
}

.dimmed {
    opacity: 0.5;
}

