@page "/apply"
@using sv_f8b8fe97cd024b68bd7edeea13057830.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (submittedApplicationId.HasValue)
    {
        <div class="alert alert-success text-center py-5">
            <h3 class="mb-3">✓ Application Submitted!</h3>
            <p class="lead">Your application has been received.</p>
            <p><strong>Application ID: @submittedApplicationId.Value</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="currentStep"
                       CompletedSteps="completedSteps"
                       OnStepClicked="GoToStep" />

        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep Model="personalInfo"
                                  ModelChanged="p => personalInfo = p"
                                  OnNext="HandlePersonalInfoNext"
                                  ApplicationService="ApplicationService" />
                break;

            case 1:
                <WorkHistoryStep Entries="workEntries"
                                 EntriesChanged="e => workEntries = e"
                                 OnNext="() => AdvanceStep()"
                                 OnBack="() => GoToStep(currentStep - 1)" />
                break;

            case 2:
                <ReferencesStep References="references"
                                ReferencesChanged="r => references = r"
                                OnNext="() => AdvanceStep()"
                                OnBack="() => GoToStep(currentStep - 1)" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="coverLetter"
                                 CoverLetterChanged="c => coverLetter = c"
                                 OnNext="() => AdvanceStep()"
                                 OnBack="() => GoToStep(currentStep - 1)" />
                break;

            case 4:
                <ReviewStep Personal="personalInfo"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="coverLetter"
                            OnEditStep="GoToStep"
                            OnSubmit="HandleSubmit"
                            OnBack="() => GoToStep(currentStep - 1)"
                            IsSubmitting="isSubmitting"
                            ErrorMessage="@submitError" />
                break;
        }
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();

    private PersonalInfo personalInfo = new("", "", "", "");
    private List<WorkEntry> workEntries = new() { new("", "", default, DateTime.Today, "") };
    private List<Reference> references = new() { new("", "", "", ""), new("", "", "", "") };
    private string coverLetter = "";

    private bool isSubmitting;
    private string? submitError;
    private int? submittedApplicationId;

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        personalInfo = info;
        AdvanceStep();
    }

    private void AdvanceStep()
    {
        completedSteps.Add(currentStep);
        if (currentStep < 4)
            currentStep++;
    }

    private void GoToStep(int step)
    {
        if (step <= currentStep || completedSteps.Contains(step))
            currentStep = step;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                personalInfo,
                new WorkHistory(workEntries),
                references,
                coverLetter
            );

            submittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

