 @using sv_f8b8fe97cd024b68bd7edeea13057830.Models

 <h4 class="mb-3">Personal Information</h4>

 @if (!string.IsNullOrEmpty(ErrorMessage))
 {
     <div class="alert alert-danger">@ErrorMessage</div>
 }

 <div class="row g-3">
     <div class="col-md-6">
         <label class="form-label">Full Name <span class="text-danger">*</span></label>
         <input type="text" class="form-control" value="@Model.FullName"
                @onchange="e => Model = Model with { FullName = (string?)e.Value ?? "" }" />
     </div>
     <div class="col-md-6">
         <label class="form-label">Email <span class="text-danger">*</span></label>
         <input type="email" class="form-control @(emailInvalid ? "is-invalid" : "")" value="@Model.Email"
                @onchange="e => Model = Model with { Email = (string?)e.Value ?? "" }" />
         @if (emailInvalid)
         {
             <div class="invalid-feedback">Please enter a valid email address.</div>
         }
     </div>
     <div class="col-md-6">
         <label class="form-label">Phone <span class="text-danger">*</span></label>
         <input type="tel" class="form-control" value="@Model.Phone"
                @onchange="e => Model = Model with { Phone = (string?)e.Value ?? "" }" />
     </div>
     <div class="col-md-6">
         <label class="form-label">Address <span class="text-danger">*</span></label>
         <input type="text" class="form-control" value="@Model.Address"
                @onchange="e => Model = Model with { Address = (string?)e.Value ?? "" }" />
     </div>
 </div>

 <div class="d-flex justify-content-end mt-4">
     <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
         @if (isValidating)
         {
             <span class="spinner-border spinner-border-sm me-1" role="status"></span>
         }
         Next
     </button>
 </div>

 @code {
     [Parameter, EditorRequired] public PersonalInfo Model { get; set; } = default!;
     [Parameter, EditorRequired] public EventCallback<PersonalInfo> ModelChanged { get; set; }
     [Parameter, EditorRequired] public EventCallback<PersonalInfo> OnNext { get; set; }
     [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

     private string? ErrorMessage;
     private bool emailInvalid;
     private bool isValidating;

     private async Task HandleNext()
     {
         ErrorMessage = null;
         emailInvalid = false;

         if (string.IsNullOrWhiteSpace(Model.FullName) ||
             string.IsNullOrWhiteSpace(Model.Email) ||
             string.IsNullOrWhiteSpace(Model.Phone) ||
             string.IsNullOrWhiteSpace(Model.Address))
         {
             ErrorMessage = "All fields are required.";
             return;
         }

         isValidating = true;
         try
         {
             var isEmailValid = await ApplicationService.ValidateEmailAsync(Model.Email);
             if (!isEmailValid)
             {
                 emailInvalid = true;
                 ErrorMessage = "The email address could not be validated.";
                 return;
             }
         }
         finally
         {
             isValidating = false;
         }

         await ModelChanged.InvokeAsync(Model);
         await OnNext.InvokeAsync(Model);
     }
 }

